def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))

    zero_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    r0 = min(r for r, c in zero_cells)
    r1 = max(r for r, c in zero_cells)
    c0 = min(c for r, c in zero_cells)
    c1 = max(c for r, c in zero_cells)

    markers = {}
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            v = grid[r][c]
            if v != 0:
                markers[v] = (r - r0, c - c0)

    counts = {v: 0 for v in markers}
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or not (r0 <= r <= r1 and c0 <= c <= c1):
                pass
            if (r, c) in seen:
                continue
            v = grid[r][c]
            if v == bg or v == 0 or v not in markers:
                continue
            if r0 <= r <= r1 and c0 <= c <= c1:
                continue
            counts[v] += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                                and grid[ny][nx] == v):
                            seen.add((ny, nx))
                            stack.append((ny, nx))

    out = [[0 for _ in range(c1 - c0 + 1)] for _ in range(r1 - r0 + 1)]
    for v, (r, c) in markers.items():
        for i in range(counts[v]):
            if c + 2 * i < len(out[0]):
                out[r][c + 2 * i] = v
    return out
